fixtures.fixed/main_test.go:
package main

import (
	"bytes"
	"testing"
)

func Example_main() {
	main()
	// Output: 16 0123456789ABCDEF
}
func TestReadHeader(t *testing.T) {
	first, second := readHeader(), readHeader()
	if len(first) != 16 || string(first) != "0123456789ABCDEF" {
		t.Fatal("wrong prefix")
	}
	first[0] = 'X'
	if second[0] != '0' {
		t.Fatal("calls share bytes")
	}
}
func TestCapacityVersusCopy(t *testing.T) {
	for _, tc := range []struct {
		name   string
		fn     func([]byte) []byte
		shares bool
	}{
		{"limited", func(b []byte) []byte { return b[:16:16] }, true},
		{"clone", func(b []byte) []byte { return bytes.Clone(b[:16]) }, false},
		{"make_copy", func(b []byte) []byte { out := make([]byte, 16); copy(out, b[:16]); return out }, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			b := []byte("0123456789ABCDEFtail")
			h := tc.fn(b)
			if string(h) != "0123456789ABCDEF" {
				t.Fatal("wrong content")
			}
			h[0] = 'X'
			if (b[0] == 'X') != tc.shares {
				t.Fatal("wrong aliasing")
			}
			if tc.shares {
				h = append(h, '!')
				if b[16] != 't' || h[16] != '!' {
					t.Fatal("append overwrote tail")
				}
			}
		})
	}
}

